#' Import data
#' 
#' @param file Data generated by \code{read_file}
#' @param format `"long"`, `"longer"`, `"wide"`
#'   or `"prepost`.
#' 
#' @returns Tibble
#' 
#' @export
import_data <- function(file, format = "long") {
  
  d0 <- list(long = NULL, longer = NULL, wide = NULL, prepost = NULL)
  
  outs <- names(file)[grepl( "_T", names(file))] # scale_time-point variables
  scls <- unique(sub("_[^_]+$", "", outs)) # scale irrespective of the time-point
  resp <- scls[c(1:4, 6, 9)] # scales for response rates calculations (no subscales)
  
  d0$longer <- file |>
    tidyr::pivot_longer(
      cols = tidyselect::all_of(outs),
      names_to = c("scale", "subscale","occasion"),
      names_sep = "_",
      values_to = "score"
    ) |>
    dplyr::mutate(
      occasion = dplyr::if_else(is.na(occasion), subscale, occasion),
      subscale = dplyr::if_else(subscale == occasion, NA, subscale)
    ) |>
    dplyr::mutate(
      STUDY_ID = factor(x = STUDY_ID),
      completed = dplyr::if_else( # manually re-code completion for subjects #130 and #148
        condition = STUDY_ID %in% c(130, 148),
        true = 0,
        false = completed
      ),
      sex = factor(
        x = dplyr::case_when(sex == "f" ~ 0, sex == "m" ~ 1),
        levels = 0:1,
        labels = c("female", "male"),
        ordered = FALSE
      ),
      laterality = factor(
        x = dplyr::case_when(laterality %in% c("P","p") ~ 0, laterality %in% c("L","l") ~ 1),
        levels = 0:1,
        labels = c("right", "left"),
        ordered = FALSE
      ),
      dg = factor(x = dg),
      stim_type = factor(
        x = dplyr::case_when(stim_type == "HF" ~ 0, stim_type == "TBS" ~ 1),
        levels = 0:1,
        labels = c("HF-rTMS", "iTBS"),
        ordered = FALSE
      ),
      dplyr::across(
        .cols = tidyselect::contains("termination"),
        .fns = \(x) dplyr::if_else(x == "", NA, x)
      ),
      occasion = factor(
        x = sub("T", "", occasion),
        levels = 0:2,
        labels = paste0("T",0:2),
        ordered = TRUE
      ),
      termination_phase = factor(
        x = dplyr::case_when(
          is.na(termination_phase)  ~ 0,
          termination_phase == "T1" ~ 1,
          termination_phase == "T2" ~ 2
        ),
        levels = 0:2,
        labels = c("none","T1","T2"),
        ordered = TRUE
      )
    ) |>
    dplyr::rename("treatment" = "stim_type")
  
  d0$long <- d0$longer |>
    dplyr::mutate(col = dplyr::if_else(
      !is.na(subscale),
      paste(scale, subscale, sep = "_"),
      scale
    )) |>
    dplyr::select(-ends_with("scale")) |>
    tidyr::pivot_wider(
      names_from = col,
      values_from = score
    )
  
  d0$prepost <- d0$longer |>
    tidyr::pivot_wider(
      names_from = occasion,
      values_from = score
    ) |>
    dplyr::rename(pre = T0) |>
    tidyr::pivot_longer(
      c(T1, T2),
      names_to = "occasion",
      names_transform = \(x) factor(x, levels = c("T1", "T2"), ordered = TRUE),
      values_to = "post"
    ) |>
    dplyr::mutate(key = dplyr::if_else(
      !is.na(subscale),
      paste(scale, subscale, sep = "_"),
      scale
    )) |>
    dplyr::select(-ends_with("scale")) |>
    tidyr::pivot_wider(
      names_from = key,
      values_from = c(pre, post),
      names_glue = "{key}_{.value}"
    )
  
  d0$wide <- d0$long |>
    tidyr::pivot_wider(
      values_from = tidyselect::all_of(scls),
      names_from = occasion
    )
  
  # Add response rates
  for (i in resp) {
    for (j in c("T1","T2")) {
      rr <- (d0$wide[, paste0(i, "_", j)] - d0$wide[, paste0(i, "_T0")]) /
        d0$wide[, paste0(i, "_T0")]
      
      # Response (i.e., at least 50% reduction compared to baseline)
      d0$wide[, paste0(i, "_", j, "_perc_decl")] <- -100 * rr
      d0$wide[, paste0(i, "_", j, "_response")]  <- ifelse(rr < -0.5, 1, 0)
    }
  }
  
  # "Manually" add remissions:
  d0$wide <- d0$wide |>
    dplyr::mutate(
      dplyr::across(tidyselect::all_of(paste0("SDS_"     , c("T1","T2"))), \(x) dplyr::if_else(x <= 49, 1, 0), .names = "{.col}_remission" ),
      dplyr::across(tidyselect::all_of(paste0("PSS_"     , c("T1","T2"))), \(x) dplyr::if_else(x <= 13, 1, 0), .names = "{.col}_remission" ),
      dplyr::across(tidyselect::all_of(paste0("BAI_"     , c("T1","T2"))), \(x) dplyr::if_else(x <=  7, 1, 0), .names = "{.col}_remission" ),
      dplyr::across(tidyselect::all_of(paste0("QIDS_"    , c("T1","T2"))), \(x) dplyr::if_else(x <=  5, 1, 0), .names = "{.col}_remission" ),
      dplyr::across(tidyselect::all_of(paste0("HAMA_tot_", c("T1","T2"))), \(x) dplyr::if_else(x <= 17, 1, 0), .names = "{.col}_remission" ),
      dplyr::across(tidyselect::all_of(paste0("HAMD_tot_", c("T1","T2"))), \(x) dplyr::if_else(x <=  7, 1, 0), .names = "{.col}_remission" )
    )
  
  # Check whether there is a difference between original and the widest data
  # (there should bo none)
  if (max(abs(file[ , outs] - d0$wide[ , outs] ), na.rm = TRUE) > 0) {
    "Imported data do not agree with the original file!"
  } else {
    d0[[format]]
  }
}
